create or replace TABLE SZD_PRODUCTION.CORE_REL.T_CUSTOMS_CLEARANCE_REPORT_2 (
	MOVEMENT_REF_NUMBER VARCHAR(250) NOT NULL COMMENT 'The movement reference number is a customs identification number that’s created each time a declaration is submitted.',
	TRADER_REFERENCE VARCHAR(250) NOT NULL COMMENT 'Descriptive attribute - This is a reference assigned by the declarant for the goods covered by the declaration.',
	AUTHORITY_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the political country_2 of the customs authority that created this clearance report.',
	IMPORTER_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the importer who initiated the customs declaration via a broker or directly.',
	IMPORTER_DECLARANT_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the importer who made the declaration to the customs authority. If not specified then the declaration was made by a broker.',
	BROKER_DECLARANT_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the broker who made the declaration to the customs authority. If not specified then the declaration was made by a importer.',
	DISPATCH_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the country_2 that dispatched the good.',
	IMPORT_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the transhipment location_2 where the goods are unloaded.',
	TRANSPORT_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique identifier of the transport mode.',
	TRANSPORT_ROUTE_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique code of the transport route type.',
	TRANSPORT_COUNTRY_LOCATION_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the political country_2 that has made the transport of the goods.',
	CUSTOMS_DECLARATION_TYPE_CD VARCHAR(50) NOT NULL COMMENT 'The unique identifier of the customs declaration type.',
	ENTRY_DT DATE NOT NULL COMMENT 'The date when the data enters the CDS system.',
	ENTRY_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'Descriptive attribute - The time when the data enters the CDS system.',
	ACCEPTANCE_DT DATE NOT NULL COMMENT 'The time when the goods have arrived at the import location.',
	CLEARANCE_DT DATE NOT NULL COMMENT 'The date on which the goods were granted clearance by Customs and any duties/taxes due were paid.',
	CLEARANCE_TMSP TIMESTAMP_TZ(9) NOT NULL COMMENT 'Descriptive attribute - The time on which the goods were granted clearance by Customs and any duties/taxes due were paid.',
	CONSIGNOR_PARTY_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the consignor.',
	CONSIGNOR_NAME VARCHAR(100) COMMENT 'Descriptive attribute -The name of the consignor.',
	CUSTOMS_VAL NUMBER(38,5) COMMENT 'Fact - additive - The total value of the item_2 for the purposes of customs duty. In addition to the actual price of the goods this includes additional elements such as freight charges to the EU boundary. ',
	TOTAL_DUTY_VAL NUMBER(38,5) COMMENT 'Fact - additive - The total amount of customs duty actually paid outright for the whole declaration.',
	TOTAL_VAT_VAL NUMBER(38,5) COMMENT 'Fact - additive - The total value of the item_2 for purposes of VAT. This can differ from the Customs Value - for example, it includes any customs duty paid together with freight charges from the EU to the UK boundary.',
	TOTAL_VAT_PAID_VAL NUMBER(38,5) COMMENT 'Fact - additive - The total amount of VAT paid on the whole declaration.',
	TOTAL_CAP_VAL NUMBER(38,5) COMMENT 'Fact - additive - The total amount of CAP value.',
	TOTAL_EXCISE_VAL NUMBER(38,5) COMMENT 'Fact - additive - The total amount of excise on the whole declaration.',
	INVOICE_AUTH_COUNTRY_CURR_CD VARCHAR(50) NOT NULL COMMENT 'The code identifying the currency, according to ISO 4217. This is the currency of the country_2 where the goods are imported in.',
	INVOICE_AUTH_COUNTRY_VAL NUMBER(38,5) COMMENT 'Fact - additive - The value of the invoice in the currency of the country_2 where the goods are imported in.',
	INVOICE_TRUST_CURR_CD VARCHAR(50) NOT NULL COMMENT 'The code identifying the currency, according to ISO 4217. This is the currency of the used by the trust.',
	INVOICE_TRUST_VAL NUMBER(38,5) COMMENT 'Fact - additive - The value of the invoice in the currency used by the trust.',
	PAYING_AGENT_NUMBER VARCHAR(250) COMMENT 'Descriptive attribute - Number of the organization who will  pay taxes and duties.',
	TOTAL_PACKAGES_CNT NUMBER(38,0) NOT NULL COMMENT 'Total count of all packages of a declaration.',
	DECLARATION_UCR VARCHAR(250) COMMENT 'Descriptive attribute - This is a unique consignment reference for the goods covered by the declaration. The reference can be used to identify the entry for amendment or cancellation and is used for inventory linking. On a declaration the UCR may be a reference allocated by a forwarder or one chosen by the declarant, possibly allocated by the exporter, seller, buyer or importer.',
	FIRST_DEFERMENT NUMBER(38,0) COMMENT 'Descriptive attribute - The first deferment approval number to identify the deferment account_2 to which revenue is to be debited.',
	SECOND_DEFERMENT NUMBER(38,0) COMMENT 'Descriptive attribute - The second deferment approval number to identify the deferment account_2 to which revenue is to be debited.',
	AIR_TRANSPORT_ADJUST_COST_CURR_CD VARCHAR(50) NOT NULL COMMENT 'The currency code used for specifiying the amount of air transport cost adjustments.',
	AIR_TRANSPORT_ADJUST_COST_VAL NUMBER(38,5) COMMENT 'Fact - additive - The cost amount for air transport adjustments.',
	VAT_ADJUSTMENT_CURR_CD VARCHAR(50) NOT NULL COMMENT 'The currency code used for specifiying the amount of VAT value adjustments.',
	VAT_ADJUSTMENT_VAL NUMBER(38,5) COMMENT 'Fact - additive - The value for the VAT adjustment.',
	TRANSPORT_ADJUST_COST_CURR_CD VARCHAR(50) NOT NULL COMMENT 'The currency code used for specifiying the amount of transport cost adjustments.',
	TRANSPORT_ADJUST_COST_VAL NUMBER(38,5) COMMENT 'Fact - additive - The amount of the transport cost adjustments.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_SRC_FILE_NAME VARCHAR(500) COMMENT 'Contains the name(s) of the input file(s) that delivered the record. It can be either the full path of the BLOG storage or the shortened file path',
	DWH_SRC_1_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The extraction timestamp of the record from the source',
	constraint PK_CUSTOMS_CLEARANCE_REPORT primary key (MOVEMENT_REF_NUMBER, TRADER_REFERENCE)
)COMMENT='Entity - Transactional Events - Snapshot_2 - A report from a customs authority containing the results of customs clearance for declared/imported goods. - Source - Excel Report from CDS (per Mail)'
;